<?php
/**  * Export Job Orders for Staff  * Formats: Excel, CSV, PDF  */
if (session_status() === PHP_SESSION_NONE) session_start();  require_once __DIR__ . '/../lib.php';
require_once __DIR__ . '/../../public/db_connect.php';
require_login();  $me = current_user();
$role = role_key($me['role'] ?? '');
$staff_id = (int)$me['id'];
$format = strtolower(trim($_GET['format'] ?? 'excel'));  // Only staff roles can access
if (!in_array($role, ['staff', 'cashier', 'pump_attendant'])) {  die('Access denied');
}  try {  // Fetch job orders created by this staff member  $stmt = $pdo->prepare("  SELECT  COALESCE(jo.job_order_id, jo.job_order_number, CONCAT('JO-', jo.id)) AS jo_id,  COALESCE(jo.customer_name, 'Walk-in') AS customer,  COALESCE(jo.service_type, jo.service_description, 'N/A') AS service,  COALESCE(jo.vehicle_plate, 'N/A') AS vehicle,  jo.status,  COALESCE(jo.total_cost, jo.estimated_cost, 0) AS amount,  COALESCE(jo.payment_method, 'N/A') AS payment_method,  DATE_FORMAT(jo.created_at, '%Y-%m-%d %H:%i') AS date_created  FROM job_orders jo  WHERE jo.created_by = ?  ORDER BY jo.created_at DESC  LIMIT 1000  ");  $stmt->execute([$staff_id]);  $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);  if ($format === 'csv') {  // ── CSV Export ──  header('Content-Type: text/csv; charset=utf-8');  header('Content-Disposition: attachment; filename="job_orders_' . date('Y-m-d') . '.csv"');  $output = fopen('php://output', 'w');  fputcsv($output, ['Job Order ID', 'Customer', 'Service', 'Vehicle', 'Status', 'Amount', 'Payment Method', 'Date Created']);  foreach ($rows as $row) {  fputcsv($output, [  $row['jo_id'],  $row['customer'],  $row['service'],  $row['vehicle'],  $row['status'],  '₱' . number_format((float)$row['amount'], 2),  $row['payment_method'],  $row['date_created']  ]);  }  fclose($output);  exit;  } elseif ($format === 'pdf') {  // ── PDF Export ──  header('Content-Type: application/pdf');  header('Content-Disposition: attachment; filename="job_orders_' . date('Y-m-d') . '.pdf"');  echo '<html><head><style>  body { font-family: Arial, sans-serif; font-size: 11px; }  table { width: 100%; border-collapse: collapse; margin-top: 20px; }  th { background: #002F70; color: white; padding: 8px; text-align: left; font-size: 10px; }  td { border: 1px solid #ddd; padding: 6px; font-size: 10px; }  h1 { color: #002F70; font-size: 18px; }  </style></head><body>';  echo '<h1>Job Orders Export</h1>';  echo '<p>Generated: ' . date('F d, Y H:i A') . '</p>';  echo '<table><thead><tr>';  echo '<th>JO ID</th><th>Customer</th><th>Service</th><th>Vehicle</th><th>Status</th><th>Amount</th><th>Payment</th><th>Date</th>';  echo '</tr></thead><tbody>';  foreach ($rows as $row) {  echo '<tr>';  echo '<td>' . htmlspecialchars($row['jo_id']) . '</td>';  echo '<td>' . htmlspecialchars($row['customer']) . '</td>';  echo '<td>' . htmlspecialchars($row['service']) . '</td>';  echo '<td>' . htmlspecialchars($row['vehicle']) . '</td>';  echo '<td>' . htmlspecialchars($row['status']) . '</td>';  echo '<td>₱' . number_format((float)$row['amount'], 2) . '</td>';  echo '<td>' . htmlspecialchars($row['payment_method']) . '</td>';  echo '<td>' . htmlspecialchars($row['date_created']) . '</td>';  echo '</tr>';  }  echo '</tbody></table>';  echo '<script>window.print();</script>';  echo '</body></html>';  exit;  } else {  // ── Excel Export (HTML table with Excel headers) ──  header('Content-Type: application/vnd.ms-excel');  header('Content-Disposition: attachment; filename="job_orders_' . date('Y-m-d') . '.xls"');  echo '<table border="1"><thead><tr>';  echo '<th>Job Order ID</th><th>Customer</th><th>Service</th><th>Vehicle</th><th>Status</th><th>Amount</th><th>Payment Method</th><th>Date Created</th>';  echo '</tr></thead><tbody>';  foreach ($rows as $row) {  echo '<tr>';  echo '<td>' . htmlspecialchars($row['jo_id']) . '</td>';  echo '<td>' . htmlspecialchars($row['customer']) . '</td>';  echo '<td>' . htmlspecialchars($row['service']) . '</td>';  echo '<td>' . htmlspecialchars($row['vehicle']) . '</td>';  echo '<td>' . htmlspecialchars($row['status']) . '</td>';  echo '<td>₱' . number_format((float)$row['amount'], 2) . '</td>';  echo '<td>' . htmlspecialchars($row['payment_method']) . '</td>';  echo '<td>' . htmlspecialchars($row['date_created']) . '</td>';  echo '</tr>';  }  echo '</tbody></table>';  exit;  }  } catch (Exception $e) {  die('Export failed: ' . $e->getMessage());
}
